/**
 * Reorders the rows of a tabular dataset based on a custom sequence
 * defined in a provided list, using the "name" column as the key.
 * 
 * @param {Array<Object>} dataset - Array of objects representing table rows
 * @param {Array<string>} sequenceList - Array of names in desired order
 * @returns {Array<Object>} Reordered dataset
 */
function reorderTableByNameSequence(dataset, sequenceList) {
  // Validate inputs
  if (!Array.isArray(dataset) || !Array.isArray(sequenceList)) {
    throw new Error('Both dataset and sequenceList must be arrays');
  }

  if (dataset.length === 0) {
    return dataset;
  }

  // Create a map of sequence positions for O(1) lookup
  const sequenceMap = new Map(
    sequenceList.map((name, index) => [name, index])
  );

  // Sort dataset based on sequence list
  const reorderedDataset = [...dataset].sort((a, b) => {
    const posA = sequenceMap.has(a.name) ? sequenceMap.get(a.name) : Infinity;
    const posB = sequenceMap.has(b.name) ? sequenceMap.get(b.name) : Infinity;

    // Items in sequence list come first (in sequence order)
    // Items not in sequence list come last (maintain original relative order)
    if (posA === Infinity && posB === Infinity) {
      return dataset.indexOf(a) - dataset.indexOf(b);
    }

    return posA - posB;
  });

  return reorderedDataset;
}

