   * Calculates the percentage of missing entries for each column in a dataset
   * @param {Array<Array>} df0 - A 2D array where rows are observations and columns are variables
   * @returns {Object} An object with column names/indices as keys and missing percentages as values
   */

  if (!df0 || df0.length === 0) {
    return {};
  }

  const numRows = df0.length;
  const numCols = df0[0].length;
  const missingRates = {};

  // Iterate through each column
  for (let colIndex = 0; colIndex < numCols; colIndex++) {
    let missingCount = 0;

    // Count missing values in the column
    for (let rowIndex = 0; rowIndex < numRows; rowIndex++) {
      const value = df0[rowIndex][colIndex];

      // Check if value is missing (null, undefined, NaN, or empty string)
      if (value === null || value === undefined || 
          (typeof value === 'number' && isNaN(value)) || 
          value === '') {
        missingCount++;
      }
    }

    // Calculate percentage
    const missingPercentage = (missingCount / numRows) * 100;
    missingRates[`column_${colIndex}`] = missingPercentage;
  }

  return missingRates;
}

