 * @param {string} str0 - The name of the timestamp column
 * @param {number} var0 - The duration of the time window (in milliseconds or the same unit as timestamps)
 * @returns {Array<Object>} - The dataframe with an added "moving_avg" column
 */
function computeMovingAverage(df0, str0, var0) {
  // Validate inputs
  if (!Array.isArray(df0) || df0.length === 0) {
    throw new Error('Input dataframe must be a non-empty array');
  }

