    throw new Error('Window duration must be a positive number');
  }

  // Verify that required columns exist
  if (!df0[0].hasOwnProperty(str0)) {
    throw new Error(`Column "${str0}" not found in dataframe`);
  }

  if (!df0[0].hasOwnProperty('value')) {
