/**
 * Filters a 2D table based on multiple conditions
 * @param {Array<Array>} table - The 2D table data to filter
 * @param {Array<{column: string|number, operator: string, value: any}>} conditions - Array of filter conditions
 * @param {Object} [options] - Optional configuration
 * @param {boolean} [options.includeAllRows=false] - Whether to include rows that don't match any condition
 * @returns {Array<Array>} Filtered table rows
 */
function filterTable(table, conditions, options = {}) {
    // Validate input
    if (!Array.isArray(table) || !table.length) {
        throw new Error('Table must be a non-empty 2D array');
    }

    if (!Array.isArray(conditions)) {
        throw new Error('Conditions must be an array');
    }

    // Get column headers from first row if available
    const headers = table[0];
    const isHeaderRow = Array.isArray(headers) && headers.length > 0;

    // Create a mapping of column names to indices
    const columnMap = {};
    if (isHeaderRow) {
        headers.forEach((header, index) => {
            columnMap[header] = index;
        });
    }

    // Default options
    const { includeAllRows = false } = options;

    return table.filter((row, rowIndex) => {
        // Skip header row if present
        if (isHeaderRow && rowIndex === 0) return true;

        // Check if row matches any condition
        let matchesAny = false;

        for (const condition of conditions) {
            const { column, operator, value } = condition;

            // Resolve column index
            let colIndex;
            if (typeof column === 'string' || typeof column === 'number') {
                if (typeof column === 'string') {
                    if (!columnMap[column]) {
                        throw new Error(`Column '${column}' not found in table`);
                    }
                    colIndex = columnMap[column];
                } else {
                    colIndex = column;
                }
            } else {
                throw new Error('Column must be a string (header name) or number (index)');
            }

            // Skip if column index is invalid
            if (colIndex >= row.length) {
                throw new Error(`Column index ${colIndex} is out of bounds for row`);
