    // Get column index (handle both numeric index and header names)
    let colIdx = columnIndex;
    if (typeof columnIndex === 'string') {
      const headers = tf.getHeadersText();
      colIdx = headers.indexOf(columnIndex);
      if (colIdx === -1) {
        console.warn(`Column "${columnIndex}" not found`);
        return;
      }
    }

    // Apply filter based on type
    switch (type.toLowerCase()) {
      case 'equals':
        tf.setFilterValue(colIdx, `=${value}`);
        break;
      case 'startswith':
        tf.setFilterValue(colIdx, `^${value}`);
        break;
      case 'endswith':
        tf.setFilterValue(colIdx, `${value}$`);
        break;
      case 'contains':
