/**
 * Resets the row index of a table and converts existing index values into new columns
 * @param {HTMLElement} tableElement - The table element to process
 * @param {Object} [options] - Configuration options
 * @param {string} [options.indexColumnName='Index'] - Name for the new index column
 * @param {boolean} [options.preserveOriginalIndex=false] - Whether to keep original index values
 * @returns {HTMLElement} The modified table element
 */
function reindexTable(tableElement, options = {}) {
    // Default options
    const {
        indexColumnName = 'Index',
        preserveOriginalIndex = false
    } = options;

    // Validate input
    if (!(tableElement instanceof HTMLElement) || tableElement.tagName !== 'TABLE') {
        throw new Error('First argument must be a table element');
    }

    // Clone the table to avoid modifying the original directly
    const tableClone = tableElement.cloneNode(true);

    // Get the table body
    const tbody = tableClone.querySelector('tbody');
    if (!tbody) {
        throw new Error('Table must have a tbody element');
    }

    // Get all rows (excluding header if present)
    const rows = Array.from(tbody.querySelectorAll('tr')).filter(row => !row.querySelector('th'));

    if (rows.length === 0) {
        console.warn('No data rows found in table');
        return tableElement;
    }

    // Create a new column for the index
    const indexHeader = document.createElement('th');
    indexHeader.textContent = indexColumnName;
    const headerRow = tableClone.querySelector('thead tr');
    if (headerRow) {
        headerRow.appendChild(indexHeader);
    } else {
        // Create header if it doesn't exist
        const newHeader = document.createElement('thead');
        const newHeaderRow = document.createElement('tr');
        newHeaderRow.appendChild(indexHeader);
        newHeader.appendChild(newHeaderRow);
        tableClone.insertBefore(newHeader, tbody);
    }

    // Process each row
    rows.forEach((row, index) => {
        // Create new index cell
        const indexCell = document.createElement('td');
        indexCell.textContent = index + 1; // 1-based index

        // Insert at the beginning of the row
        row.insertBefore(indexCell, row.firstChild);

        // If preserving original index, add it as a data attribute
        if (preserveOriginalIndex) {
            const originalIndexCell = document.createElement('td');
            originalIndexCell.textContent = index;
            originalIndexCell.setAttribute('data-original-index', 'true');
            row.insertBefore(originalIndexCell, indexCell.nextSibling);
        }
    });

    // Replace the original table with the modified clone
    tableElement.parentNode.replaceChild(tableClone, tableElement);

    return tableClone;
}

