 * @param {string} identifierKey - The property name to use as identifier
 * @returns {Array<Object>} Array with only first occurrence of each identifier
 */
function removeDuplicateRows(data, identifierKey) {
  if (!Array.isArray(data) || data.length === 0) {
    return data;
