function assignOrderLabels(inputList) {
  const mapping = {}; // Maps unique elements to their labels
  const labels = [];  // Stores the label for each element in input
  let currentLabel = 0;

  for (const element of inputList) {
    // Convert element to string key for consistent object key handling
    const key = JSON.stringify(element);

