/**
 * Count occurrences of tuples in a sequence with filtering, ordering, and limiting
 * @param {Array<Array>} sequence - Array of tuples to count
 * @param {Object} options - Configuration object
 * @param {Function} options.filter - Filter predicate function (tuple) => boolean
 * @param {string} options.sortBy - Sort by 'count' or 'tuple' (default: 'count')
 * @param {string} options.sortOrder - 'asc' or 'desc' (default: 'desc')
 * @param {number} options.limit - Maximum number of results to return
 * @param {boolean} options.stringifyTuples - Convert tuples to strings for counting (default: true)
 * @returns {Array<{tuple: Array, count: number}>} Array of counted tuples with counts
 */
function countTuples(sequence, options = {}) {
  // Validate input
  if (!Array.isArray(sequence)) {
    throw new TypeError('Sequence must be an array');
  }

  // Extract options with defaults
  const {
    filter = null,
    sortBy = 'count',
    sortOrder = 'desc',
    limit = null,
    stringifyTuples = true
  } = options;

  // Validate options
  if (filter && typeof filter !== 'function') {
    throw new TypeError('Filter must be a function');
  }
  if (!['count', 'tuple'].includes(sortBy)) {
    throw new Error("sortBy must be 'count' or 'tuple'");
  }
  if (!['asc', 'desc'].includes(sortOrder)) {
    throw new Error("sortOrder must be 'asc' or 'desc'");
  }
  if (limit !== null && (!Number.isInteger(limit) || limit < 1)) {
    throw new Error('Limit must be a positive integer');
  }

  // Helper function to stringify tuples for use as Map keys
  const tupleKey = (tuple) => {
    if (!stringifyTuples) return tuple;
    return JSON.stringify(tuple);
  };

  // Helper function to compare tuples
  const tuplesEqual = (t1, t2) => {
    if (t1.length !== t2.length) return false;
    return t1.every((val, idx) => val === t2[idx]);
  };

  // Count occurrences using a Map
  const tupleCounts = new Map();

  for (const tuple of sequence) {
    // Validate tuple is an array
    if (!Array.isArray(tuple)) {
      throw new TypeError('Each element in sequence must be an array (tuple)');
    }

    // Apply filter if provided
    if (filter && !filter(tuple)) {
      continue;
    }

    // Create key for Map
    const key = tupleKey(tuple);

    // Update count
    if (tupleCounts.has(key)) {
      tupleCounts.set(key, {
        tuple,
        count: tupleCounts.get(key).count + 1
      });
    } else {
      tupleCounts.set(key, {
        tuple,
        count: 1
      });
    }
  }

  // Convert Map to array
  let results = Array.from(tupleCounts.values());

  // Sort results
  results.sort((a, b) => {
    let compareValue;

    if (sortBy === 'count') {
      compareValue = a.count - b.count;
    } else {
      // Sort by tuple (lexicographically)
      compareValue = JSON.stringify(a.tuple).localeCompare(
        JSON.stringify(b.tuple)
