```javascript
/**
 * Calculates the sum of values in a specified column for rows matching a condition
 * @param {Array<Object>} data - The tabular dataset (array of objects)
 * @param {string} columnName - The name of the column to sum
 * @param {Function} condition - A predicate function that takes a row and returns boolean
 * @returns {number} The sum of values in the specified column for matching rows
 */
function conditionalColumnSum(data, columnName, condition) {
  // Validate input parameters
  if (!Array.isArray(data) || data.length === 0) {
    throw new Error('Data must be a non-empty array');
  }

  if (typeof columnName !== 'string') {
    throw new Error('Column name must be a string');
  }

  if (typeof condition !== 'function') {
    throw new Error('Condition must be a function');
  }

  // Filter rows based on condition and sum the specified column
  const sum = data
    .filter(row => condition(row))
    .reduce((accumulator, row) => {
      const value = row[columnName];

      // Ensure the value is a number
      const numValue = Number(value);

      if (isNaN(numValue)) {
        console.warn(`Non-numeric value found in column "${columnName}":`, value);
        return accumulator;
      }

      return accumulator + numValue;
    }, 0);

  return sum;
}

// ===== EXAMPLE USAGE =====

