 * @returns {string} HTML table string
 */
function createHTMLTable(table) {
  let html = '<table border="1" cellpadding="8" cellspacing="0">\n';

  // Add header row
  html += '  <thead>\n    <tr>\n';
  table.headers.forEach(header => {
    html += `      <th>${escapeHtml(String(header))}</th>\n`;
  });
  html += '    </tr>\n  </thead>\n';

  // Add data rows
