        // Create a filter function for this condition
        const filterFn = (row) => {
            const rowValue = row[condition.column];
            const value = condition.value;

            // Handle different operators
            switch (condition.operator) {
                case '==':
                    return rowValue == value;
                case '!=':
                    return rowValue != value;
                case '>':
                    return rowValue > value;
                case '<':
                    return rowValue < value;
                case '>=':
