  const finalColumnOrder = [...priorityColumns, ...remainingColumns];

  // Reconstruct table object in desired column order
  const reorderedTable = {};
  finalColumnOrder.forEach(col => {
    reorderedTable[col] = mergedTable[col];
  });

  return reorderedTable;
}

