  // Group the data by the specified column
  const grouped = {};

  df0.forEach(row => {
    const groupKey = row[var0];
    if (!grouped[groupKey]) {
      grouped[groupKey] = [];
    }
    grouped[groupKey].push(row);
  });

  // Convert grouped data into a table with multi-level index
  const indexedData = [];
  const indices = [];

  Object.entries(grouped).forEach(([groupValue, rows]) => {
    rows.forEach((row, rowIndex) => {
      // Create a multi-level index: [groupValue, rowIndex]
      const multiIndex = [groupValue, rowIndex];
      indices.push(multiIndex);
      indexedData.push(row);
