# Merge by Sequence Function

```javascript
/**
 * Combines multiple lists into a single list by following a sequence pattern.
 * The sequence specifies which input list (by index) to draw from at each step.
 * 
 * @param {Array<Array>} lists - Array of input lists to merge
 * @param {Array<number>} sequence - Sequence of indices indicating which list to draw from
 * @returns {Array} - Single merged list following the sequence pattern
 * 
 * @example
 * const result = mergeBySequence(
 *   [[1, 2, 3], ['a', 'b', 'c'], [10, 20]],
 *   [0, 1, 2, 0, 1, 0, 2, 1]
 * );
 * // Returns: [1, 'a', 10, 2, 'b', 3, 20, 'c']
 */
function mergeBySequence(lists, sequence) {
  // Validate inputs
  if (!Array.isArray(lists) || !Array.isArray(sequence)) {
    throw new Error('Both lists and sequence must be arrays');
  }

  if (lists.length === 0) {
    return [];
  }

  // Initialize trackers for each list's current position
  const positions = new Array(lists.length).fill(0);
  const result = [];

  // Follow the sequence pattern
  for (const listIndex of sequence) {
    // Validate sequence index
    if (typeof listIndex !== 'number' || listIndex < 0 || listIndex >= lists.length) {
      throw new Error(`Invalid sequence index: ${listIndex}. Must be between 0 and ${lists.length - 1}`);
    }

    const currentList = lists[listIndex];
    const currentPosition = positions[listIndex];

    // Check if we still have elements in this list
    if (currentPosition < currentList.length) {
      result.push(currentList[currentPosition]);
      positions[listIndex]++;
    }
    // If the list is exhausted, we skip this sequence entry (silent skip)
  }

  return result;
}

// Example usage:
