function fillMissingWithColMean(matrix) {
    if (!Array.isArray(matrix) || matrix.length === 0) {
        throw new Error("Input must be a non-empty two-dimensional array.");
    }

    const numRows = matrix.length;
    const numCols = matrix[0].length;

    // Check if all rows have the same number of columns
    for (let row of matrix) {
        if (row.length !== numCols) {
            throw new Error("All rows must have the same number of columns.");
        }
    }

    // Calculate the mean for each column
    const colMeans = Array(numCols).fill(0);
    const colCounts = Array(numCols).fill(0);

    for (let col = 0; col < numCols; col++) {
        for (let row = 0; row < numRows; row++) {
            const value = matrix[row][col];
            if (value !== null && value !== undefined) {
                colMeans[col] += value;
                colCounts[col] += 1;
            }
        }
        colMeans[col] /= colCounts[col] || 1;
    }

    // Replace missing entries with the column mean
    for (let col = 0; col < numCols; col++) {
        for (let row = 0; row < numRows; row++) {
            if (matrix[row][col] === null || matrix[row][col] === undefined) {
                matrix[row][col] = colMeans[col];
            }
        }
    }

    return matrix;
}

