# JavaScript Function: Sort Collection by Reference Sequence

```javascript
function sortByReference(dict0, lst0, var0) {
  /**
   * Sorts a collection of records according to the order defined by a reference sequence.
   * 
   * @param {Array<Object>} dict0 - Collection of records to sort
   * @param {Array} lst0 - Reference sequence defining the sort order
   * @param {string} var0 - Key in each record whose value determines sort position
   * @returns {Array<Object>} - Sorted collection
   */

  // Create a map of reference values to their positions for O(1) lookup
  const referenceMap = new Map();
  lst0.forEach((value, index) => {
    referenceMap.set(value, index);
  });

  // Sort the collection based on reference sequence positions
  return dict0.sort((a, b) => {
    const positionA = referenceMap.get(a[var0]);
    const positionB = referenceMap.get(b[var0]);

    // Handle cases where values might not exist in reference sequence
    // Values not in reference sequence are pushed to the end
    const aPos = positionA !== undefined ? positionA : Infinity;
    const bPos = positionB !== undefined ? positionB : Infinity;

    return aPos - bPos;
  });
}

// Example Usage:
const dict0 = [
  { name: 'Alice', priority: 'high' },
  { name: 'Bob', priority: 'low' },
  { name: 'Charlie', priority: 'medium' },
  { name: 'David', priority: 'high' }
];

const lst0 = ['low', 'medium', 'high'];
const var0 = 'priority';

const sortedResult = sortByReference(dict0, lst0, var0);
console.log(sortedResult);
