  const df0Selected = df0.map(row => {
    const selectedRow = {};
    selectedColumns.forEach(col => {
      if (col in row) {
        selectedRow[col] = row[col];
      }
    });
    return selectedRow;
  });

  // Create a lookup map from df1 for efficient matching
  const df1Map = new Map();
  df1.forEach(row => {
