```javascript
/**
 * Computes the Cartesian product of two sequences of coordinate values
 * @param {number[]} xCoords - First sequence of coordinate values
 * @param {number[]} yCoords - Second sequence of coordinate values
 * @returns {Array<[number, number]>} Array of [x, y] coordinate pairs
