# JavaScript Function for Range-Based Subset Extraction

```javascript
const RangeExtractor = require('range-extractor');

/**
 * Extracts a subset from a list of text entries using range indices.
 * 
 * @param {string[]} entries - The list of text entries to extract from
 * @param {number} startIndex - The starting index (inclusive)
 * @param {number} endIndex - The ending index (inclusive)
 * @returns {string[]} The extracted subset of entries
 * @throws {Error} If indices are out of bounds or invalid
 */
function extractRangeSubset(entries, startIndex, endIndex) {
  // Validate inputs
  if (!Array.isArray(entries)) {
    throw new Error('Input must be an array');
  }

  if (typeof startIndex !== 'number' || typeof endIndex !== 'number') {
    throw new Error('Start and end indices must be numbers');
  }

  if (startIndex < 0 || endIndex >= entries.length) {
    throw new Error(
      `Indices out of bounds. Valid range: 0 to ${entries.length - 1}`
    );
  }

  if (startIndex > endIndex) {
    throw new Error('Start index cannot be greater than end index');
  }

  // Create a range string for the extractor
  const rangeString = `${startIndex}-${endIndex}`;

  // Use RangeExtractor to parse the range
  const extractor = new RangeExtractor();
  const ranges = extractor.parse(rangeString);

  // Extract the subset based on the parsed ranges
  const subset = [];
  for (const range of ranges) {
    for (let i = range.start; i <= range.end; i++) {
      if (i < entries.length) {
        subset.push(entries[i]);
      }
    }
  }

  return subset;
}

// Example usage
const textEntries = [
  'Apple',
  'Banana',
  'Cherry',
  'Date',
  'Elderberry',
  'Fig',
  'Grape'
];

try {
  const result = extractRangeSubset(textEntries, 2, 5);
  console.log('Extracted subset:', result);
  // Output: ['Cherry', 'Date', 'Elderberry', 'Fig']
} catch (error) {
  console.error('Error:', error.message);
}
```

## Key Features

- **Range Parsing**: Uses `range-extractor` library to parse range notation
- **Input Validation**: Checks for valid array input and index bounds
- **Inclusive Bounds**: Both start and end indices are inclusive
- **Error Handling**: Throws descriptive errors for invalid inputs
- **Self-contained**: All logic wrapped in a single, reusable function

## Usage Example

```javascript
const items = ['A', 'B', 'C', 'D', 'E', 'F'];

// Extract items from index 1 to 4
const subset = extractRangeSubset(items, 1, 4);
console.log(subset); // ['B', 'C', 'D', 'E']
```

