 * Compute the frequency of each unique pair of values in two table columns
 * @param {Array<Object>} table - Array of objects representing the table
 * @param {string} col1 - Name of the first column
 * @param {string} col2 - Name of the second column
 * @returns {Array<[[any, any], number]>} Array of tuples with [pair, count]
 */
function computePairFrequency(table, col1 = 'col1', col2 = 'col2') {
  // Extract pairs from the table
