/**
 * Sorts text elements with selective descending order for specified positions
 * @param {string[]} texts - Array of text elements to sort
 * @param {number[]} [descendingPositions=[]] - Positions (0-indexed) to sort in descending order
 * @returns {string[]} - Sorted array
 */
function selectiveSortTexts(texts, descendingPositions = []) {
  // Create array of objects with original indices and values
  const indexed = texts.map((text, index) => ({
    value: text,
    index: index,
    shouldDescend: descendingPositions.includes(index)
  }));

  // Use selective-sort to partition elements
  const { selected, rest } = selectiveSort(
    indexed,
    (item) => item.shouldDescend
  );

  // Sort ascending elements
  const ascendingSorted = rest.sort((a, b) => 
    a.value.localeCompare(b.value)
  );

  // Sort descending elements
  const descendingSorted = selected.sort((a, b) => 
    b.value.localeCompare(a.value)
  );

  // Merge back maintaining original position intent
