  let ascIndex = 0;
  let descIndex = 0;

  for (let i = 0; i < indexed.length; i++) {
    if (descendingPositions.includes(i)) {
      result[i] = descendingSorted[descIndex++].value;
    } else {
      result[i] = ascendingSorted[ascIndex++].value;
    }
  }

  return result;
}

