  const uniqueIndices = uniqueRows(identifiers.map((id, idx) => [id, idx]));

  // Map back to original data using the indices
  const result = uniqueIndices
    .map(([id, idx]) => idx)
    .sort((a, b) => a - b)
    .map(idx => data[idx]);

  return result;
}

