        const dy = (jacobian[0][0] * f2 - jacobian[1][0] * f1) / det;

        // Update solution
        prevX = x;
        prevY = y;
        x -= dx;
        y -= dy;

        // Check convergence
        if (Math.abs(x - prevX) < tolerance && Math.abs(y - prevY) < tolerance) {
            return { x, y, converged: true };
        }
